 </template>

 <template v-else-if="page==='tasks'">
 <Panel title="任务筛选"><template #actions><a-input v-model:value="query" placeholder="搜索任务名称、关键词或编号…" allow-clear style="width:270px"><template #prefix><Icon name="SearchOutlined"/></template></a-input></template><div class="filter-row"><a-select v-model:value="projectFilter" :options="options(['全部项目',...projects])"/><a-select v-model:value="statusFilter" :options="options(['全部状态','未开始','进行中','待处理','已完成'])"/><a-select v-model:value="priorityFilter" :options="options(['全部优先级','高','中','低'])"/><a-select v-model:value="ownerFilter" :options="options(['全部负责人',...members])"/><a-select v-model:value="categoryFilter" :options="options(['全部分类',...new Set(tasks.map(t=>t.category))])"/></div><div class="filter-row"><a-range-picker :default-value="[dayjs('2026-10-20'),dayjs('2026-10-20')]"/><div class="grow"/><a-button @click="showDetail('更多筛选')"><Icon name="FilterOutlined"/> 更多筛选</a-button><a-button @click="resetFilters">重置</a-button></div></Panel>
 <Panel title="任务列表"><template #actions><small>共 {{filteredTasks.length}} 项</small><a-button @click="statusFilter='已完成'">查看已完成</a-button><a-button @click="exportData"><Icon name="DownloadOutlined"/> 导出</a-button><a-button type="primary" @click="openCreate()">＋ 新建任务</a-button></template><a-table class="task-table" :columns="taskColumns" :data-source="filteredTasks" :row-selection="{}" :pagination="{pageSize:10,showSizeChanger:false,showTotal:n=>`共 ${n} 项`}" size="small" :scroll="{x:680}"><template #bodyCell="{column,record}"><a v-if="column.dataIndex==='name'" class="table-link" @click="showDetail(record.name)">{{record.name}} <small>♧ {{record.key%8+1}}</small></a><span v-else-if="column.dataIndex==='owner'" class="person"><Avatar :index="members.indexOf(record.owner)"/>{{record.owner}}</span><a-tag v-else-if="['priority','status','category'].includes(column.dataIndex)" :color="colorFor(record[column.dataIndex])">{{record[column.dataIndex]}}</a-tag><Icon v-else-if="column.key==='remind'" name="BellFilled" :style="{color:record.priority==='高'?'#ff646b':'#93a6c0'}"/><a-button v-else-if="column.key==='action'" type="text" @click="showDetail(record.name)">···</a-button></template></a-table></Panel>
 </template>

 <template v-else-if="page==='calendar'">
 <div class="dashboard-grid calendar-grid"><div class="stack"><Panel title="日历视图"><template #actions><a-button size="small" @click="month=month.subtract(1,'month')">‹</a-button><b>{{month.format('YYYY年M月')}}</b><a-button size="small" @click="month=month.add(1,'month')">›</a-button><a-button size="small" @click="month=dayjs('2026-10-01');selectedDay=20">今天</a-button></template><div class="calendar"><span v-for="w in ['日','一','二','三','四','五','六']" :key="w" class="weekday">{{w}}</span><button v-for="(d,i) in calendarCells" :key="d.key" :class="{muted:d.muted,selected:d.day===selectedDay&&!d.muted}" @click="selectedDay=d.day"><span>{{d.day}}</span><i v-if="!d.muted&&[1,6,12,13,14,19,20,21,22,29].includes(d.day)" :style="{background:palette[i%4]}"/></button></div><div class="calendar-legend"><span v-for="(s,i) in ['会议','任务','里程碑','重要事项']" :key="s"><i class="dot" :style="{background:palette[i]}"/> {{s}}</span></div></Panel><Panel title="今日会议" more="查看全部" @more="showDetail('全部会议')"><div v-for="(m,i) in meetings.slice(0,3)" :key="m.name" class="meeting-card" :style="{'--accent':palette[i]}"><small>{{m.time.split(' – ')[0]}}<br/>{{m.time.split(' – ')[1]}}</small><div class="grow"><b>{{m.name}}</b><p>{{m.desc}}</p><small><Icon name="EnvironmentOutlined"/> {{m.room}}</small></div><Avatars/><a-tag :color="['blue','green','red'][i]">{{m.status}}</a-tag></div></Panel><Panel title="任务提醒" more="查看全部" @more="go('tasks')"><div v-for="(t,i) in tasks.slice(0,4)" :key="t.key" class="reminder-row"><small>{{['09:00','11:00','14:00','16:00'][i]}}</small><Icon name="BellFilled" :style="{color:palette[i]}"/><span class="grow">{{t.name}}</span><a-tag :color="colorFor(t.priority)">{{t.priority}}优先级</a-tag></div></Panel></div><div class="stack"><Panel :title="selectedDate+'　'+['星期日','星期一','星期二','星期三','星期四','星期五','星期六'][month.date(selectedDay).day()]"><template #actions><a-button size="small" @click="openCreate('日程')">＋</a-button></template><div v-for="(m,i) in meetings" :key="m.name" class="schedule-row expanded" @click="showDetail(m.name)"><small>{{m.time}}</small><i :style="{background:palette[i%5]}"/><div class="grow"><b>{{m.name}}</b><p>{{m.desc}}</p><small><Icon name="EnvironmentOutlined"/> {{m.room}}</small><div><Avatars/></div></div><a-tag :color="i===0?'blue':i===1?'green':'red'">{{m.status}}</a-tag></div></Panel><Panel title="重要里程碑" more="查看全部" @more="go('progress')"><div v-for="(s,i) in ['项目第一阶段交付','产品上线发布','客户验收会议','项目总结汇报']" :key="s" class="milestone-mini"><span class="date-square">{{i<2?'10月':'11月'}}<b>{{[22,28,5,15][i]}}</b></span><i class="dot" :style="{background:palette[i]}"/><div class="grow"><b>{{s}}</b><p>完成阶段目标与项目成果验收</p></div><a-tag>{{[3,8,16,26][i]}}天后</a-tag></div></Panel><Panel title="近期日程" more="查看全部" @more="showDetail('近期日程')"><div v-for="(s,i) in ['技术方案评审会','产品迭代计划会','运营推广方案讨论','产品上线发布会']" :key="s" class="recent-schedule"><small>10月{{21+i*2}}日</small><i class="dot" :style="{background:palette[i]}"/><b>{{s}}</b><small>10:00 – 11:00</small></div></Panel></div></div>
 </template>

 <template v-else-if="page==='progress'">
 <div class="dashboard-grid progress-grid"><Panel title="项目进度计划"><template #actions><a-select size="small" default-value="按周视图" :options="options(['按周视图','按月视图'])"/></template><div class="gantt"><div class="gantt-heading"><b>任务名称</b><span>2026年10月<br/><small>10月5日　10月12日　10月19日　10月26日　11月2日</small></span></div><div class="today-line"><span>今天</span></div><template v-for="(group,i) in ['需求分析阶段','产品设计阶段','开发实现阶段','测试上线阶段']" :key="group"><div class="gantt-row group"><b>⌄ {{group}}</b><strong>{{[100,80,40,0][i]}}%</strong></div><div v-for="(n,j) in [['需求调研与分析','需求文档编写'],['产品原型设计','UI界面设计','设计评审'],['前端开发','后端开发','单元测试'],['系统测试','发布准备','正式上线']][i]" :key="n" class="gantt-row"><span>{{n}}</span><small>{{[100,80,40,0][i]}}%</small><div class="gantt-track"><i :style="{left:`${8+i*13+j*9}%`,width:`${25+j*6}%`,background:`linear-gradient(90deg,${palette[i]},${palette[i]}55)`,opacity:i===3?.3:1}"/></div></div></template></div></Panel><div class="stack"><Panel title="项目里程碑" more="全部里程碑" @more="showDetail('全部里程碑')"><div v-for="(s,i) in ['需求分析完成','产品设计评审','开发版本发布','系统测试完成','项目正式上线']" :key="s" class="milestone-line"><span :class="{pending:i>2}" :style="{background:i<3?palette[i===2?0:1]:'white'}">{{i<3?'✓':''}}</span><div class="grow"><b>{{s}}</b><small>{{['2026年10月05日','2026年10月12日','2026年10月20日','2026年10月28日','2026年11月05日'][i]}}</small></div><a-tag :color="i<2?'green':i===2?'blue':'default'">{{i<2?'已完成':i===2?'进行中':'待开始'}}</a-tag></div></Panel><Panel title="项目健康度"><template #actions><a-tag color="green">♡ 整体良好</a-tag></template><Chart type="donut" :total="'62%'" caption="项目进度" :values="[62,38]" :labels="['进度状态','成本控制']" :colors="['#10c997','#d6e3f1']"/><div class="health-status"><span>资源使用 <b>良好</b></span><span>风险状态 <b>可控</b></span></div></Panel></div></div><Panel title="阶段进度" more="全部阶段" @more="showDetail('全部阶段')"><div class="stage-grid"><article v-for="(s,i) in ['需求分析阶段','产品设计阶段','开发实现阶段','测试上线阶段']" :key="s"><b><span class="mini-icon" :style="{background:palette[i]}"><Icon :name="projectIcons[i]"/></span>{{s}}</b><a-progress :percent="[100,80,40,0][i]" :stroke-color="palette[i]" size="small"/><a-tag :color="i===0?'blue':i===3?'default':'green'">{{i===0?'已完成':i===3?'未开始':'进行中'}}</a-tag><small>2026年10月{{[5,12,28,28][i]}}日</small></article></div></Panel><div class="dashboard-grid"><Panel title="进度偏差分析"><template #actions><small>● 计划进度　<span class="green">● 实际进度</span></small></template><Chart :values="[0,20,40,62,85,95,100]"/></Panel><Panel title="近期风险与问题" more="全部" @more="go('risks')"><div v-for="(r,i) in risks.slice(0,4)" :key="r.id" class="risk-mini"><span class="mini-icon" :style="{background:palette[i]}">!</span><div class="grow"><b>{{r.title}}</b><p>请及时跟进处理并同步项目进展</p></div><a-tag :color="colorFor(r.level)">{{r.level}}</a-tag></div></Panel></div>
 </template>

 <template v-else-if="page==='team'">
 <div class="dashboard-grid home-grid"><Panel title="团队成员"><template #actions><a-button type="text" size="small" @click="showDetail('全部成员')">全部成员 ›</a-button><a-button size="small" @click="openCreate('成员')">＋ 邀请成员</a-button></template><div v-for="(m,i) in [...members,...invitedMembers]" :key="m" class="member-row"><Avatar :index="i"/><div><b>{{m}}</b><small><i class="dot" :style="{background:i===2?'#ff9e36':'#16c99b'}"/> {{i===2?'忙碌':'在线'}}</small></div><a-tag :color="['blue','orange','cyan','purple','green','red'][i%6]">{{roles[i%6]}}</a-tag><div class="grow member-work"><b>{{[8,6,5,4,3,4][i%6]}} 个任务</b><small>负责{{['项目整体推进','产品需求与规划','后端开发','界面设计','测试与质量','运营与推广'][i%6]}}</small></div><button class="text-button" @click="showDetail(m)">···</button></div></Panel><div class="stack"><Panel title="角色分工" more="查看详情" @more="showDetail('角色分工')"><Chart type="donut" :values="[1,1,1,1,1,1]" :total="6" caption="团队成员" :labels="roles" :colors="[...palette,'#ffbf19']"/></Panel><Panel title="团队公告"><template #actions><a-button size="small" @click="openCreate('公告')">＋ 发布公告</a-button></template><div class="announcement"><span class="square-icon"><Icon name="NotificationFilled"/></span><div><b>{{announcements.at(-1)||'项目第二阶段启动'}}</b><p>各位同事，项目第二阶段已正式启动，请大家按照计划积极推进，有问题及时沟通。</p><a @click="showDetail('项目第二阶段启动')">查看详情 →</a></div></div></Panel></div></div><div class="dashboard-grid"><Panel title="最近讨论" more="全部讨论" @more="showDetail('全部讨论')"><div v-for="(m,i) in members.slice(1)" :key="m" class="discussion-row" @click="showDetail('关于'+projects[i%4]+'的讨论')"><Avatar :index="i+1"/><b>{{m}}</b><span class="grow">{{['关于产品需求文档的讨论','接口开发进度同步','设计稿修改建议','运营活动方案评审','下周工作计划讨论'][i]}}</span><small>10月20日 10:30</small><a-badge :count="[8,5,12,6,3][i]" :number-style="{backgroundColor:'#e0f1ff',color:'#1685ff'}"/></div></Panel><Panel title="待我审批" more="全部审批" @more="showDetail('全部审批')"><div v-for="(s,i) in approvals" :key="s" class="approval-row"><span class="square-icon" :style="{background:palette[i]}"><Icon name="FileTextOutlined"/></span><div class="grow"><b>{{s}}</b><small>{{members[i]}} 提交于 10月20日 09:20</small></div><a-button size="small" @click="approvals=approvals.filter(a=>a!==s);message.info('已拒绝申请')">拒绝</a-button><a-button size="small" type="primary" @click="approvals=approvals.filter(a=>a!==s);message.success('已通过申请')">通过</a-button></div><a-empty v-if="!approvals.length" description="暂无待审批事项"/></Panel></div><div class="dashboard-grid"><Panel title="会议纪要" more="全部会议" @more="go('calendar')"><div v-for="(m,i) in meetings.slice(0,3)" :key="m.name" class="meeting-record"><span class="square-icon" :style="{background:palette[i]}"><Icon name="VideoCameraFilled"/></span><div class="grow"><b>{{m.name}}</b><p>{{m.desc}}</p></div><Avatars/><a-button size="small" @click="showDetail(m.name+'会议纪要')">查看记录</a-button></div></Panel><Panel title="协作动态"><div v-for="(m,i) in members.slice(0,5)" :key="m" class="activity-row"><span :style="{color:palette[i]}"><Icon :name="['FileTextFilled','CheckCircleFilled','MessageFilled','TeamOutlined','CalendarFilled'][i]"/></span><div><b>{{m}}</b> {{['上传了文件《产品需求文档 v2.1》','完成了任务 接口开发与调试','在讨论中 @了你','邀请了新成员加入','创建了项目计划'][i]}}<p>{{projects[i%4]}}</p></div><small>10:20</small></div></Panel></div>
 </template>

 <template v-else-if="page==='files'">
 <div class="dashboard-grid files-grid"><Panel title="文件夹"><template #actions><a-button size="small" @click="openCreate('文件夹')">＋ 新建文件夹</a-button></template><div class="folder-grid"><button v-for="(f,i) in [...['项目文档','产品资料','设计资源','研发文档','会议记录','市场资料'],...extraFiles]" :key="f" @click="showDetail(f)"><span class="folder" :style="{'--folder':palette[i%5]}"></span><b>{{f}}</b><small>{{[24,18,35,28,12,16][i%6]}} 个文件</small><span class="folder-menu">···</span></button></div></Panel><Panel title="文件分类"><template #actions><a-button size="small" @click="showDetail('管理文件分类')">管理</a-button></template><button v-for="(c,i) in ['全部文件','文档文件','表格文件','演示文件','图片文件','压缩文件','其他文件']" :key="c" class="file-category" :class="{chosen:fileCategory===c}" @click="fileCategory=c"><span class="mini-icon" :style="{background:palette[i%5]}"><Icon :name="i===0?'BuildFilled':'FileTextFilled'"/></span><span class="grow">{{c}}</span><small>{{[128,42,18,14,26,8,20][i]}}</small> ›</button></Panel></div><Panel title="文件列表"><template #actions><a-input v-model:value="fileSearch" placeholder="搜索文件名称、内容或上传人…" allow-clear style="width:240px"/><a-select v-model:value="fileCategory" :options="options(['全部文件','文档文件','表格文件','演示文件','图片文件'])"/></template><a-table :columns="fileColumns" :data-source="visibleFiles" :pagination="false" :row-selection="{}" :row-key="r=>r[0]" size="small"><template #bodyCell="{column,record,index}"><a v-if="column.dataIndex===0" class="file-title" @click="showDetail(record[0])"><span class="mini-icon" :style="{background:palette[index%4]}"><Icon name="FileTextFilled"/></span>{{record[0]}}</a><small v-else-if="column.key==='date'">2026年10月20日</small><a-button v-else-if="column.key==='action'" type="text" @click="showDetail(record[0])">···</a-button></template></a-table></Panel><div class="dashboard-grid home-grid"><Panel title="最近上传" more="查看更多" @more="showDetail('最近上传的文件')"><div v-for="(f,i) in ['会议纪要_2026-10-20.docx','产品评审材料.pptx','数据分析报表.xlsx','用户调研报告.pdf','活动海报设计.png']" :key="f" class="upload-row"><a-checkbox/><span class="square-icon" :style="{background:palette[i%4]}"><Icon name="FileTextFilled"/></span><div class="grow"><b>{{f}}</b><small>{{members[i]}}　上传于 2026年10月20日 14:30</small></div><small>{{[1.2,4.8,2.1,6.3,3.5][i]}} MB</small><button class="text-button" @click="showDetail(f)">···</button></div></Panel><div class="stack"><Panel title="版本历史" more="查看全部" @more="showDetail('文档版本历史')"><div v-for="(v,i) in ['v1.2','v1.1','v1.0']" :key="v" class="version-row"><i class="dot" :style="{background:i===0?palette[0]:palette[4]}"/><div><b>{{v}}</b><a-tag v-if="i===0" color="green">当前版本</a-tag><small>张三　2026年10月{{20-i}}日 14:30</small><p>{{['更新了项目实施计划内容','优化了功能需求描述','创建初始版本'][i]}}</p></div></div></Panel><Panel title="文件权限"><template #actions><a-button size="small" @click="showDetail('管理文件权限')">管理权限</a-button></template><div class="permission-line"><Icon name="TeamOutlined"/><div class="grow"><b>项目核心成员</b><small>可查看、上传、下载、编辑</small></div><span>8 人 ›</span></div><div class="permission-line"><Icon name="TeamOutlined"/><div class="grow"><b>外部协作成员</b><small>可查看、下载</small></div><span>4 人 ›</span></div></Panel></div></div>
 </template>

 <template v-else-if="page==='risks'">
 <div class="dashboard-grid home-grid"><div class="stack"><Panel title="风险分布矩阵"><div class="risk-matrix"><div class="matrix-y">影<br/>响<br/>程<br/>度</div><span class="axis high">高</span><span class="axis medium">中</span><span class="axis low">低</span><div class="matrix-cells"><div v-for="(v,i) in [1,2,3,2,3,1,2,1,0]" :key="i" :style="{background:['#ffe7e4','#ffdfc5','#ffbdb7','#def8ef','#fff0b8','#ffe5cc','#def8ef','#e3f7f0','#e7eff6'][i]}"><span :style="{background:['#ffcaca','#ff8b2b','#ff4548','#14cc97','#ffd15c','#ff9d42','#99ebd4','#a1ecd7','#d7e1ee'][i]}">{{v}}</span></div></div><div class="matrix-x">低　　　　　中　　　　　高<br/>发生概率</div></div></Panel><Panel title="待处理的关键问题" more="更多" @more="showDetail('待处理关键问题')"><div v-for="(r,i) in risks.slice(0,3)" :key="r.id" class="risk-mini" @click="showDetail(r.title)"><span class="mini-icon" :style="{background:i===0?'#ff5558':'#ff8b2b'}"><Icon name="WarningFilled"/></span><b class="grow">{{r.title}}</b><a-tag :color="colorFor(r.level)">{{r.level}}</a-tag><small>2026年10月20日</small></div></Panel></div><div class="stack"><Panel title="风险状态统计"><template #actions><a-select default-value="全部项目" size="small" :options="options(['全部项目',...projects])"/></template><Chart type="donut" :total="12" caption="总风险" :values="[3,5,4]" :labels="['高风险','中风险','低风险']" :colors="['#ff5558','#ffc52d','#0cc997']"/></Panel><Panel title="问题处理状态"><template #actions><a-select default-value="全部项目" size="small" :options="options(['全部项目',...projects])"/></template><Chart type="donut" :total="12" caption="总问题" :values="[6,3,3]" :labels="['待处理','处理中','已解决']" :colors="palette"/></Panel></div></div><Panel title="风险问题列表"><template #actions><a-select size="small" v-model:value="riskType" :options="options(['全部类型','风险','问题'])"/><a-select size="small" v-model:value="riskStatus" :options="options(['全部状态','待处理','处理中','已解决'])"/><a-select size="small" v-model:value="riskLevel" :options="options(['全部风险等级','高风险','中风险','低风险'])"/><a-button size="small" type="primary" @click="openCreate('风险/问题')">＋ 新建风险/问题</a-button></template><a-table :columns="riskColumns" :data-source="filteredRisks" row-key="id" :pagination="false" size="small" :scroll="{x:620}"><template #bodyCell="{column,record}"><a-tag v-if="['type','level','status'].includes(column.dataIndex)" :color="column.dataIndex==='type'?(record.type==='风险'?'red':'blue'):colorFor(record[column.dataIndex])">{{record[column.dataIndex]}}</a-tag><a v-else-if="column.dataIndex==='title'" class="table-link" @click="showDetail(record.title)">{{record.title}}</a><span v-else-if="column.dataIndex==='owner'" class="person"><Avatar :index="members.indexOf(record.owner)"/>{{record.owner}}</span><small v-else-if="column.key==='date'">2026年10月20日</small><a-button v-else-if="column.key==='action'" type="text" @click="showDetail(record.title)">···</a-button></template></a-table></Panel><Panel title="风险应对计划" more="更多" @more="showDetail('风险应对计划')"><div class="response-head"><span>风险/问题</span><span>应对措施</span><span>责任人</span><span>计划完成时间</span><span>状态</span></div><div v-for="(r,i) in risks.slice(0,3)" :key="r.id" class="response-row"><span>{{r.title}}</span><span>{{['增加开发资源、优化开发计划，按周跟踪进度','准备备选供应商方案，签订SLA保障协议','制定人才保留方案，推进知识交接'][i]}}</span><span class="person"><Avatar :index="i"/>{{r.owner}}</span><small>2026年10月20日</small><a-tag color="blue">执行中</a-tag></div></Panel>
 </template>

 <template v-else-if="page==='stats'">
 <div class="dashboard-grid stats-top"><Panel title="任务完成趋势"><template #actions><a-select default-value="最近7天" size="small" :options="options(['最近7天','最近30天'])"/><a-select default-value="全部项目" size="small" :options="options(['全部项目',...projects])"/></template><div class="chart-key"> <span>● 任务总数</span><span class="green">● 已完成</span><span class="orange">● 待完成</span></div><Chart/></Panel><Panel title="项目类型分布"><Chart type="donut" :values="[3,2,1,1,1]" :total="8" caption="项目总数" :labels="['产品研发','运营活动','内部管理','客户项目','其他']" :colors="palette"/></Panel></div><div class="dashboard-grid"><Panel title="项目进度分布"><template #actions><a-select default-value="全部项目" size="small" :options="options(['全部项目',...projects])"/></template><Chart type="bar" :values="[4,3,2,3,1]" :labels="['未开始','进行中','推进中','即将完成','已完成']" :colors="palette"/></Panel><Panel title="团队工作量统计"><template #actions><a-select default-value="本月" size="small" :options="options(['本月','本周'])"/></template><div class="workload-head"><span>成员</span><span>任务量　　完成率</span></div><div v-for="(m,i) in ['张三','李四','王五','赵六','陈七','孙八']" :key="m" class="workload-row"><Avatar :index="i"/><b>{{m}}</b><a-progress :percent="[88,76,72,64,58,50][i]" :stroke-color="palette[i%5]" :show-info="false" size="small"/><span>{{48-i*5}}</span><small>{{[88,76,72,64,58,50][i]}}%</small></div></Panel></div><div class="dashboard-grid"><Panel title="任务状态统计"><Chart type="donut" :values="[196,36,12,4]" :total="248" caption="总任务数"/></Panel><Panel title="项目完成率排行"><template #actions><a-select default-value="本月" size="small" :options="options(['本月','本周'])"/></template><div class="ranking-head"><span>排名</span><span>项目名称</span><span>完成率</span><span>进度</span></div><div v-for="(p,i) in projects" :key="p" class="ranking-row"><i :style="{background:['#ffb500','#a4b4c8','#dba273','#dce8f6'][i]}">{{i+1}}</i><b>{{p}}</b><span>{{[92,78,68,52][i]}}%</span><a-progress :percent="[92,78,68,52][i]" :show-info="false" :stroke-color="palette[i]" size="small"/></div></Panel></div><Panel title="关键指标趋势"><template #actions><a-radio-group v-model:value="trendTab" size="small" option-type="button" button-style="solid" :options="options(['任务完成率','项目数量','团队效率','工时统计'])"/></template><Chart :values="({任务完成率:[52,58,62,68,72,76,79],项目数量:[2,3,4,5,6,7,8],团队效率:[42,50,62,65,72,80,88],工时统计:[30,45,48,62,68,82,96]})[trendTab]"/></Panel>
 </template>

 <template v-else-if="page==='settings'">
 <div class="dashboard-grid settings-grid"><Panel title="账号信息"><template #actions><a-button type="link" size="small" @click="showDetail('编辑账号信息')">编辑资料 ›</a-button></template><div class="profile"><Avatar :index="0"/><div><h3>张明</h3><p>产品经理</p><small>zhangming@company.com</small></div></div><div v-for="(s,i) in [['所属团队','产品研发部'],['账号角色','管理员'],['加入时间','2024年03月15日'],['上次登录','2026年10月20日 08:30']]" :key="s[0]" class="account-row"><Icon :name="['TeamOutlined','SafetyCertificateOutlined','ClockCircleOutlined','UserOutlined'][i]"/><span>{{s[0]}}</span><span>{{s[1]}}</span></div></Panel><Panel title="通知设置"><p class="panel-description">选择你希望接收的通知方式和内容</p><div v-for="(s,i) in ['任务变更通知','项目动态通知','团队协作通知','日程提醒','邮件通知','短信通知']" :key="s" class="setting-row"><span class="setting-icon" :style="{color:palette[i%5],background:palette[i%5]+'18'}"><Icon :name="['BellFilled','MessageFilled','TeamOutlined','CalendarFilled','MailFilled','PhoneFilled'][i]"/></span><div class="grow"><b>{{s}}</b><p>{{['任务创建、更新、完成等提醒','项目进度、里程碑变更提醒','成员加入、评论、@我的提醒','会议、任务截止时间提醒','重要通知通过邮件发送','紧急事项通过短信发送'][i]}}</p></div><a-switch v-model:checked="notificationValues[i]" size="small"/></div></Panel><Panel title="显示偏好"><p class="panel-description">自定义系统的外观和显示方式</p><div class="preference-row"><Icon name="BgColorsOutlined"/><span>主题模式</span><a-radio-group v-model:value="theme" :options="options(['浅色模式','深色模式','跟随系统'])"/></div><div class="preference-row"><Icon name="DesktopOutlined"/><span>界面语言</span><a-select v-model:value="language" :options="options(['简体中文'])"/></div><div class="preference-row"><b>Aa</b><span>字体大小</span><a-select v-model:value="fontSize" :options="options(['标准（推荐）','大号'])"/></div><div class="preference-row"><Icon name="AppstoreOutlined"/><span>界面密度</span><a-select v-model:value="density" :options="options(['舒适','紧凑'])"/></div></Panel><Panel title="项目默认设置"><p class="panel-description">新建项目时的默认配置</p><div v-for="(label,i) in ['默认项目模板','默认项目状态','默认开始日期','默认项目优先级','默认项目成员']" :key="label" class="preference-row"><Icon :name="['FolderOutlined','AimOutlined','CalendarOutlined','FlagOutlined','TeamOutlined'][i]"/><span>{{label}}</span><a-select v-if="i===0" v-model:value="defaultBoard" :options="options(['标准项目模板','敏捷项目模板'])"/><a-select v-if="i===1" v-model:value="defaultStatus" :options="options(['进行中','未开始'])"/><a-date-picker v-if="i===2" :default-value="dayjs('2026-10-20')"/><a-select v-if="i===3" v-model:value="defaultPriority" :options="options(['中优先级','高优先级','低优先级'])"/><a-select v-if="i===4" v-model:value="defaultMembers" :options="options(['从当前团队选择','暂不添加'])"/></div></Panel><Panel title="权限设置"><p class="panel-description">管理团队成员的系统权限</p><button v-for="(s,i) in ['成员与角色管理','项目权限控制','功能权限配置','操作日志']" :key="s" class="settings-link" @click="showDetail(s)"><span class="setting-icon" :style="{background:palette[i]+'15',color:palette[i]}"><Icon :name="['TeamOutlined','SafetyCertificateFilled','FileTextFilled','ProfileFilled'][i]"/></span><div class="grow"><b>{{s}}</b><p>{{['添加成员、分配角色和权限','设置不同项目的访问权限','控制系统功能的使用权限','查看系统操作记录'][i]}}</p></div>›</button></Panel><Panel title="第三方集成"><p class="panel-description">连接常用工具，提升工作效率</p><div v-for="(s,i) in ['Slack','钉钉','飞书','GitHub']" :key="s" class="integration-row"><span class="integration-icon" :style="{color:palette[i]}"><Icon :name="['SlackOutlined','DingdingOutlined','SendOutlined','GithubFilled'][i]"/></span><div class="grow"><b>{{s}}</b><p>{{['接收项目动态通知','同步任务与消息','团队协作与日程同步','关联代码仓库与任务'][i]}}</p></div><small><i class="dot" :style="{background:i%2===0?palette[1]:palette[4]}"/> {{i%2===0?'已连接':'未连接'}}</small><a-button size="small" @click="showDetail(s+'集成配置')">{{i%2===0?'配置':'连接'}}</a-button></div></Panel><Panel title="安全设置"><div v-for="(s,i) in ['修改密码','两步验证','登录设备管理','安全提醒']" :key="s" class="security-row"><Icon :name="['LockOutlined','SafetyOutlined','DesktopOutlined','WarningOutlined'][i]"/><b>{{s}}</b><small class="grow">{{['定期更换密码，保障账号安全','开启后登录更安全','管理已登录的设备','异常登录、风险操作提醒'][i]}}</small><a-switch v-if="i===3" v-model:checked="securityAlert" size="small"/><a-button v-else size="small" @click="showDetail(s)">{{['修改','管理','查看'][i]}}</a-button></div></Panel><Panel title="数据备份与同步"><div v-for="(s,i) in ['自动备份','上次备份时间','数据同步','导出数据']" :key="s" class="security-row"><Icon :name="['CloudUploadOutlined','HistoryOutlined','SyncOutlined','FileTextOutlined'][i]"/><b>{{s}}</b><small class="grow">{{['系统每日自动备份项目数据','2026年10月20日 02:00','与云端同步最新数据','导出个人项目数据'][i]}}</small><a-switch v-if="i===0" v-model:checked="autoBackup" size="small"/><a-button v-else-if="i>1" size="small" @click="i===3?exportData():message.success('数据已同步')">{{i===2?'立即同步':'导出'}}</a-button></div></Panel></div>
 </template>
 </main>
</div>
<a-modal v-model:open="modal" :title="'新建'+modalKind" ok-text="保存" cancel-text="取消" @ok="save"><a-form layout="vertical"><a-form-item :label="modalKind+'名称'" required><a-input v-model:value="draft" :placeholder="'请输入'+modalKind+'名称'" @press-enter="save"/></a-form-item><a-alert message="内容保存在本次演示会话中，刷新后恢复示例数据。" type="info" show-icon/></a-form></a-modal>
<a-drawer v-model:open="detail" :title="detailTitle" :width="420"><a-descriptions :column="1" bordered><a-descriptions-item label="名称">{{detailTitle}}</a-descriptions-item><a-descriptions-item label="所属项目">内容管理系统</a-descriptions-item><a-descriptions-item label="负责人">张明</a-descriptions-item><a-descriptions-item label="状态"><a-tag color="blue">进行中</a-tag></a-descriptions-item><a-descriptions-item label="更新日期">2026年10月20日</a-descriptions-item></a-descriptions><p style="margin-top:20px;color:#7a8ca5">这是静态演示详情，后续可接入实际业务数据。</p></a-drawer>
</a-config-provider>
</template>

